//! Constant data tables of the engine, generated by `tools/gen_tables.py` from the `.rodata` / `.data` /
//! `.dtcm` bytes of the reference ELF (never retyped from the C literals). The C modules re-export them
//! (`crate::dsp::wavetable::sine_table`, ...).
//!
//! Regenerate with `python3 -I tools/gen_tables.py <lxr_v1.7_gcc11.3.elf> crates/lxr-core/src/tables`.

pub mod cc2_text;
pub mod checksums;
pub mod distortion;
pub mod init_kit;
pub mod midi_note_numbers;
pub mod parameters;
pub mod transient_tables;
pub mod wavetable;

/// Little-endian byte image of a table element, as stored in the firmware (used by the checksum test).
pub trait LeBytes {
    fn le_bytes(&self, out: &mut Vec<u8>);
}

macro_rules! le_prim {
    ($($t:ty),*) => {$(
        impl LeBytes for $t {
            fn le_bytes(&self, out: &mut Vec<u8>) {
                out.extend_from_slice(&self.to_le_bytes());
            }
        }
    )*};
}
le_prim!(u8, i8, u16, i16, u32, i32, f32, f64);

impl<T: LeBytes, const N: usize> LeBytes for [T; N] {
    fn le_bytes(&self, out: &mut Vec<u8>) {
        for x in self {
            x.le_bytes(out);
        }
    }
}

impl LeBytes for crate::menu::ModTarg {
    fn le_bytes(&self, out: &mut Vec<u8>) {
        // C layout: uint8_t nameIdx @0, (padding byte, 0 in the image) @1, uint16_t param @2
        out.push(self.nameIdx);
        out.push(0);
        out.extend_from_slice(&self.param.to_le_bytes());
    }
}

/// FNV-1a 64 bit hash.
pub fn fnv1a64(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in data {
        h ^= b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

#[cfg(test)]
mod tests {
    use super::*;

    fn image<T: LeBytes>(t: &T) -> Vec<u8> {
        let mut v = Vec::new();
        t.le_bytes(&mut v);
        v
    }

    #[test]
    fn tables_match_reference_elf() {
        let tables: Vec<(&str, Vec<u8>)> = vec![
            ("sine_table", image(&wavetable::sine_table)),
            ("sawTable", image(&wavetable::sawTable)),
            ("triTable", image(&wavetable::triTable)),
            ("recTable", image(&wavetable::recTable)),
            ("transientData", image(&transient_tables::transientData)),
            ("transientVolumeTable", image(&transient_tables::transientVolumeTable)),
            ("table_1n914", image(&distortion::table_1n914)),
            ("ecc83Table", image(&distortion::ecc83Table)),
            ("MidiNoteFrequencies", image(&midi_note_numbers::MidiNoteFrequencies)),
            ("initKit", image(&init_kit::initKit)),
            ("modTargets", image(&cc2_text::modTargets)),
            ("parameterOrder", image(&parameters::parameterOrder)),
        ];
        assert_eq!(tables.len(), checksums::CHECKSUMS.len());
        for (name, bytes) in &tables {
            let (_, _, size, hash) = checksums::CHECKSUMS.iter().find(|c| c.0 == *name).expect(name);
            assert_eq!(bytes.len(), *size, "{name}: length");
            assert_eq!(fnv1a64(bytes), *hash, "{name}: checksum");
        }
    }

    #[test]
    fn table_shapes_and_spot_values() {
        assert_eq!(wavetable::sine_table.len(), 4097);
        assert_eq!(wavetable::sawTable.len(), 11);
        assert_eq!(wavetable::sawTable[0].len(), 1024);
        assert_eq!(transient_tables::transientData.len(), 12);
        assert_eq!(transient_tables::transientData[0].len(), 2205);
        assert_eq!(transient_tables::transientVolumeTable.len(), 69);
        assert_eq!(distortion::table_1n914.len(), 257);
        assert_eq!(distortion::ecc83Table.len(), 129);
        assert_eq!(midi_note_numbers::MidiNoteFrequencies.len(), 128);
        assert_eq!(init_kit::initKit.len(), 254);
        assert_eq!(cc2_text::modTargets.len(), 229);
        assert_eq!(parameters::parameterOrder.len(), 247);
        // sine table (wavetable.c:21): one period of -cos, first value -32767, maximum in the middle
        assert_eq!(wavetable::sine_table[0], -32767);
        assert!(wavetable::sine_table[2048] > 32000);
        // init kit name "Initkit"
        assert_eq!(&init_kit::initKit[..7], b"Initkit");
        // A4 = 440 Hz is MIDI note 69
        assert_eq!(midi_note_numbers::MidiNoteFrequencies[69], 440.0);
    }
}
